import { promises as fs } from 'fs'
import { join } from 'path'
import type { Logger, Runner } from '../types'
import { detectSdlPads, RYUJINX_SDL_HINTS, type SdlPad } from './sdl-pads'
import { PresetDeferredError, type ApplyPresets, type PresetContext } from './types'

/**
 * Ryujinx presets (docs/emulator-setup.md, "Fullscreen and controllers"), for Ryubing 1.3.3 (Config.json version 70,
 * SDL2 input backend).
 *
 * - A partial Config.json is not safe (Ryujinx loads zeros and dereferences missing objects), so a missing
 *   `E\portable\Config.json` is first generated by Ryujinx itself: started hidden, it saves its defaults before any
 *   window is built, and is stopped as soon as the file parses. Every later edit is a JSON merge that keeps all other
 *   keys and their order.
 * - Fullscreen: `start_fullscreen` true, only the first time.
 * - Controllers: Ryujinx has no automatic assignment; each `input_config` entry binds one concrete device id derived
 *   from the SDL GUID. The pads are enumerated with Ryujinx's own SDL2.dll and hints, and `input_config` is replaced by
 *   one GamepadSDL2 entry per pad (players 1-4) only while it is still the untouched default (the single keyboard on
 *   player 1) and a pad was found. The ids PlayOut wrote are kept in `E\portable\playout-controllers.json`, so
 *   {@link refreshRyujinxControllers} (before each launch) can follow pad changes in those entries only.
 */

/** The Config.json format this module knows. */
export const RYUJINX_CONFIG_VERSION = 70
const MAX_PLAYERS = 4
const RYUJINX_EXE = 'Ryujinx.exe'

/** One `input_config` entry (only the keys this module reads are typed). */
export interface InputConfigEntry {
  backend?: string
  id?: string
  name?: string
  player_index?: string
  [key: string]: unknown
}

interface RyujinxConfig {
  version?: number
  start_fullscreen?: boolean
  input_config?: InputConfigEntry[]
  [key: string]: unknown
}

/** `E\portable\playout-controllers.json`: the controller ids PlayOut wrote into Config.json. */
interface ControllerState {
  ids: string[]
}

const hex = (b: number): string => b.toString(16).padStart(2, '0')

/** The 16 bytes of a 32-character hex GUID (memory order). */
export function guidBytes(guidHex: string): number[] {
  const bytes: number[] = []
  for (let i = 0; i < 32; i += 2) bytes.push(parseInt(guidHex.slice(i, i + 2), 16))
  return bytes
}

/**
 * Ryujinx's controller id for the n-th connected pad with these SDL GUID bytes (SDL2GamepadDriver.GenerateGamepadId:
 * `n + "-0000" + guid.ToString()[4..]`, where System.Guid prints the first three groups little-endian).
 */
export function ryujinxPadId(bytes: number[], n: number): string {
  const b = bytes.map(hex)
  return `${n}-0000${b[1]}${b[0]}-${b[5]}${b[4]}-${b[7]}${b[6]}-${b[8]}${b[9]}-${b.slice(10, 16).join('')}`
}

/** Detected pads as Ryujinx ids, in SDL's order (the n of identical GUIDs counted in that order; empty GUIDs skipped). */
export function ryujinxPadIds(pads: SdlPad[]): { id: string; name: string }[] {
  const seen = new Map<string, number>()
  const out: { id: string; name: string }[] = []
  for (const pad of pads) {
    if (/^0+$/.test(pad.guid)) continue
    const n = seen.get(pad.guid) ?? 0
    seen.set(pad.guid, n + 1)
    out.push({ id: ryujinxPadId(guidBytes(pad.guid), n), name: pad.name })
  }
  return out
}

/** Ryujinx's display name for a pad: the SDL name (at most 50 characters) plus " (k)", k unique among `taken`. */
function displayName(sdlName: string, taken: Set<string>): string {
  const base = sdlName.length > 50 ? `${sdlName.slice(0, 47)}...` : sdlName
  let k = 0
  while (taken.has(`${base} (${k})`)) k++
  return `${base} (${k})`
}

/**
 * The GamepadSDL2 entry Ryujinx's Input settings build when a controller is picked
 * (InputViewModel.LoadDefaultConfiguration): Pro Controller, Xbox face-button layout unless the name says Nintendo.
 */
export function gamepadEntry(id: string, name: string, playerIndex: string): InputConfigEntry {
  const nintendo = /nintendo/i.test(name)
  return {
    left_joycon_stick: {
      joystick: 'Left',
      invert_stick_x: false,
      invert_stick_y: false,
      rotate90_cw: false,
      stick_button: 'LeftStick'
    },
    right_joycon_stick: {
      joystick: 'Right',
      invert_stick_x: false,
      invert_stick_y: false,
      rotate90_cw: false,
      stick_button: 'RightStick'
    },
    deadzone_left: 0.1,
    deadzone_right: 0.1,
    range_left: 1,
    range_right: 1,
    trigger_threshold: 0.5,
    motion: {
      motion_backend: 'GamepadDriver',
      sensitivity: 100,
      gyro_deadzone: 1,
      enable_motion: true
    },
    rumble: { strong_rumble: 1, weak_rumble: 1, enable_rumble: false },
    led: { enable_led: false, turn_off_led: false, use_rainbow: false, led_color: 0 },
    left_joycon: {
      button_minus: 'Back',
      button_l: 'LeftShoulder',
      button_zl: 'LeftTrigger',
      button_sl: 'SingleLeftTrigger0',
      button_sr: 'SingleRightTrigger0',
      dpad_up: 'DpadUp',
      dpad_down: 'DpadDown',
      dpad_left: 'DpadLeft',
      dpad_right: 'DpadRight'
    },
    right_joycon: {
      button_plus: 'Start',
      button_r: 'RightShoulder',
      button_zr: 'RightTrigger',
      button_sl: 'SingleLeftTrigger1',
      button_sr: 'SingleRightTrigger1',
      button_x: nintendo ? 'X' : 'Y',
      button_b: nintendo ? 'B' : 'A',
      button_y: nintendo ? 'Y' : 'X',
      button_a: nintendo ? 'A' : 'B'
    },
    version: 1,
    backend: 'GamepadSDL2',
    id,
    name,
    controller_type: 'ProController',
    player_index: playerIndex
  }
}

/** True while `input_config` is still Ryujinx's untouched default: one keyboard (id "0") on player 1. */
export function isDefaultInput(input: unknown): boolean {
  if (!Array.isArray(input) || input.length !== 1) return false
  const e = input[0] as InputConfigEntry
  return e?.backend === 'WindowKeyboard' && e.id === '0' && e.player_index === 'Player1'
}

/**
 * Merge the detected pads into `input` (pure). Returns the new array and the ids PlayOut now owns, or null when
 * nothing changes.
 *
 * - Untouched default + at least one pad: replaced by one entry per pad (Player1..Player4).
 * - Otherwise only the entries whose id is in `owned` are PlayOut's. When pads are detected and they differ from those
 *   entries, the detected pads (not already bound by one of the user's entries) take the player slots the user's
 *   entries leave free, in order; owned entries of pads that are not connected keep any slot left over, so they still
 *   bind when plugged in. An owned entry for the same id is kept as it is (only its player moves).
 * - No pad detected: nothing changes.
 */
export function mergeControllers(
  input: InputConfigEntry[],
  pads: { id: string; name: string }[],
  owned: string[]
): { input: InputConfigEntry[]; owned: string[] } | null {
  if (pads.length === 0) return null
  const isOwned = (e: InputConfigEntry): boolean =>
    e?.backend === 'GamepadSDL2' && typeof e.id === 'string' && owned.includes(e.id)

  const base = isDefaultInput(input) ? [] : input
  const ownedEntries = base.filter(isOwned)
  if (!isDefaultInput(input) && ownedEntries.length === 0) return null

  const userEntries = base.filter((e) => !isOwned(e))
  const usedSlots = new Set(userEntries.map((e) => e.player_index))
  const userIds = new Set(userEntries.map((e) => e.id))
  const freeSlots: string[] = []
  for (let p = 1; p <= MAX_PLAYERS; p++) {
    if (!usedSlots.has(`Player${p}`)) freeSlots.push(`Player${p}`)
  }

  const wanted = pads.filter((p) => !userIds.has(p.id))
  const detected = new Set(wanted.map((p) => p.id))
  const leftovers = ownedEntries.filter((e) => !detected.has(e.id as string))
  const taken = new Set(
    userEntries.map((e) => e.name).filter((n): n is string => typeof n === 'string')
  )
  const next: InputConfigEntry[] = []
  let slot = 0
  for (const pad of wanted) {
    if (slot >= freeSlots.length) break
    const previous = ownedEntries.find((e) => e.id === pad.id)
    const entry = previous
      ? { ...previous, player_index: freeSlots[slot] }
      : gamepadEntry(pad.id, displayName(pad.name, taken), freeSlots[slot])
    if (typeof entry.name === 'string') taken.add(entry.name)
    next.push(entry)
    slot++
  }
  for (const e of leftovers) {
    if (slot >= freeSlots.length) break
    next.push({ ...e, player_index: freeSlots[slot] })
    slot++
  }
  if (next.length === 0) return null

  const result = [...userEntries, ...next]
  if (JSON.stringify(result) === JSON.stringify(input)) return null
  return { input: result, owned: next.map((e) => e.id as string) }
}

/** Config.json as parsed plus how to write it back (line endings kept, no BOM). */
interface ConfigFile {
  data: RyujinxConfig
  text: string
  eol: string
}

async function readConfig(file: string): Promise<ConfigFile | null> {
  let text: string
  try {
    text = await fs.readFile(file, 'utf8')
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null
    throw err
  }
  const body = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text
  try {
    const data = JSON.parse(body) as RyujinxConfig
    if (!data || typeof data !== 'object' || Array.isArray(data)) return null
    return { data, text, eol: body.includes('\r\n') ? '\r\n' : '\n' }
  } catch {
    return null
  }
}

/**
 * readConfig for polling a file Ryujinx may be writing right now: a sharing violation (EBUSY, EPERM, EACCES) counts as
 * "not there yet" instead of failing.
 */
async function tryReadConfig(file: string): Promise<ConfigFile | null> {
  try {
    return await readConfig(file)
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code
    if (code === 'EBUSY' || code === 'EPERM' || code === 'EACCES') return null
    throw err
  }
}

/** Write a file through a temporary file and a rename, so a reader never sees it half written. */
async function writeAtomic(file: string, text: string): Promise<void> {
  const tmp = `${file}.playout-tmp`
  await fs.writeFile(tmp, text, 'utf8')
  try {
    await fs.rename(tmp, file)
  } catch (err) {
    await fs.rm(tmp, { force: true }).catch(() => undefined)
    throw err
  }
}

/** Write Config.json with .NET's indented layout (2 spaces), only when it changed. */
async function writeConfig(file: string, cfg: ConfigFile): Promise<boolean> {
  const next = JSON.stringify(cfg.data, null, 2).replace(/\n/g, cfg.eol)
  if (next === cfg.text) return false
  await writeAtomic(file, next)
  return true
}

async function readState(file: string): Promise<ControllerState | null> {
  try {
    const data = JSON.parse(await fs.readFile(file, 'utf8')) as ControllerState
    return Array.isArray(data?.ids) ? { ids: data.ids.filter((i) => typeof i === 'string') } : null
  } catch {
    return null
  }
}

async function writeState(file: string, state: ControllerState): Promise<void> {
  await writeAtomic(file, JSON.stringify(state, null, 2) + '\n')
}

/** Where Ryujinx reads its config: `E\Config.json` wins when it exists (never created), else the portable one. */
async function configPath(E: string): Promise<string> {
  const beside = join(E, 'Config.json')
  try {
    await fs.access(beside)
    return beside
  } catch {
    return join(E, 'portable', 'Config.json')
  }
}

const statePath = (E: string): string => join(E, 'portable', 'playout-controllers.json')

/** Whether a Ryujinx.exe process is running (tasklist; false when tasklist itself fails). */
export async function isRyujinxRunning(run: Runner): Promise<boolean> {
  const r = await run('tasklist', ['/FI', `IMAGENAME eq ${RYUJINX_EXE}`, '/NH', '/FO', 'CSV'], {
    timeoutMs: 15_000
  })
  return r.code === 0 && r.stdout.toLowerCase().includes(`"${RYUJINX_EXE.toLowerCase()}"`)
}

/**
 * Whether a generated Config.json is complete: it parses, has a numeric version at least the known one (a newer Ryubing
 * writes a higher one) and an input_config array.
 */
function isComplete(cfg: ConfigFile | null): boolean {
  return (
    !!cfg &&
    typeof cfg.data.version === 'number' &&
    cfg.data.version >= RYUJINX_CONFIG_VERSION &&
    Array.isArray(cfg.data.input_config)
  )
}

/** True when Config.json comes from a newer Ryujinx than this module knows (its input format may differ). */
const isNewerFormat = (cfg: ConfigFile): boolean =>
  typeof cfg.data.version === 'number' && cfg.data.version > RYUJINX_CONFIG_VERSION

/**
 * Let Ryujinx write its default Config.json: start it hidden (it saves the defaults before building any window), poll
 * until the file is complete, then stop it. Returns false (logged) on timeout or when Ryujinx exits first.
 */
export async function generateRyujinxConfig(
  ctx: Pick<PresetContext, 'emuDir' | 'log' | 'startHidden'>,
  file: string,
  options: { timeoutMs?: number; intervalMs?: number } = {}
): Promise<boolean> {
  const timeoutMs = options.timeoutMs ?? 60_000
  const intervalMs = options.intervalMs ?? 250
  const proc = ctx.startHidden(join(ctx.emuDir, RYUJINX_EXE), [], { cwd: ctx.emuDir })
  let exited = false
  void proc.exited.then(
    () => (exited = true),
    () => (exited = true)
  )
  const deadline = Date.now() + timeoutMs
  try {
    for (;;) {
      if (isComplete(await tryReadConfig(file))) return true
      if (exited) {
        // One last look: the file may have been completed just before the exit.
        if (isComplete(await tryReadConfig(file))) return true
        ctx.log.warn('Ryujinx exited before writing its default Config.json')
        return false
      }
      if (Date.now() >= deadline) {
        ctx.log.warn('Ryujinx did not write its default Config.json in time')
        return false
      }
      await new Promise((r) => setTimeout(r, intervalMs))
    }
  } finally {
    await proc.stop()
  }
}

/** Detect the pads with Ryujinx's own SDL2.dll; null when the DLL is missing or detection failed (logged). */
async function detectPads(
  E: string,
  run: Runner,
  log: Logger
): Promise<{ id: string; name: string }[] | null> {
  const dll = join(E, 'SDL2.dll')
  try {
    await fs.access(dll)
  } catch {
    log.info('Ryujinx has no SDL2.dll; controllers left as they are')
    return null
  }
  const pads = await detectSdlPads(run, log, dll, RYUJINX_SDL_HINTS)
  return pads ? ryujinxPadIds(pads) : null
}

/** True when an entry uses a backend this module does not write for (a newer SDL3 build): leave input alone then. */
const hasNewerBackend = (input: InputConfigEntry[]): boolean =>
  input.some((e) => typeof e?.backend === 'string' && /^GamepadSDL(?!2$)/.test(e.backend))

/**
 * Apply the controller merge to a loaded config (changes `cfg.data` in place). Returns the new controller state when
 * the entries changed, null when nothing changed.
 */
async function mergeInto(
  E: string,
  cfg: ConfigFile,
  run: Runner,
  log: Logger,
  state: ControllerState
): Promise<ControllerState | null> {
  const input = cfg.data.input_config
  if (!Array.isArray(input) || hasNewerBackend(input)) return null
  if (isNewerFormat(cfg)) {
    log.info(
      `Ryujinx Config.json version ${cfg.data.version} is newer than ${RYUJINX_CONFIG_VERSION}; controllers left as they are`
    )
    return null
  }
  const owns = input.some((e) => e?.backend === 'GamepadSDL2' && state.ids.includes(e.id ?? ''))
  if (!isDefaultInput(input) && !owns) return null
  const pads = await detectPads(E, run, log)
  if (!pads) return null
  if (pads.length === 0) {
    log.info('No game controller detected for Ryujinx; controllers left as they are')
    return null
  }
  const merged = mergeControllers(input, pads, state.ids)
  if (!merged) return null
  cfg.data.input_config = merged.input
  log.info(
    `Ryujinx controllers: ${merged.input.map((e) => `${e.player_index}=${e.name}`).join(', ')}`
  )
  return { ids: merged.owned }
}

export const applyPresets: ApplyPresets = async (ctx) => {
  const { emuDir: E, log, run } = ctx
  const file = await configPath(E)
  if (await isRyujinxRunning(run)) {
    throw new PresetDeferredError('Ryujinx is running; its presets are left for the next launch')
  }
  let cfg = await readConfig(file)
  if (!cfg) {
    let present = true
    try {
      await fs.access(file)
    } catch {
      present = false
    }
    if (present) throw new Error(`Ryujinx's Config.json cannot be read (${file})`)
    await fs.mkdir(join(E, 'portable'), { recursive: true })
    if (!(await generateRyujinxConfig(ctx, file)))
      throw new Error('Ryujinx did not write its default Config.json')
    cfg = await readConfig(file)
    if (!cfg) throw new Error(`Ryujinx's generated Config.json cannot be read (${file})`)
  }

  // A newer format: start_fullscreen only when that key still exists there.
  if (ctx.firstTime && (!isNewerFormat(cfg) || 'start_fullscreen' in cfg.data))
    cfg.data.start_fullscreen = true

  const state = (await readState(statePath(E))) ?? { ids: [] }
  const nextState = await mergeInto(E, cfg, run, log, state)
  // Ryujinx may have been started while the pads were detected: it would overwrite the file on exit.
  if (await isRyujinxRunning(run)) {
    throw new PresetDeferredError('Ryujinx was started; its presets are left for the next launch')
  }
  if (await writeConfig(file, cfg)) log.info('Ryujinx Config.json updated')
  // The state file also marks Ryujinx as managed by PlayOut, so a later launch can still set up a pad found then.
  await writeState(statePath(E), nextState ?? state)
}

/**
 * Before each Ryujinx launch: re-detect the pads and update only the controller entries PlayOut wrote (or the untouched
 * default keyboard entry, when no pad was found at setup). Does nothing when the presets never ran, Ryujinx is
 * running, SDL2.dll is missing or detection fails.
 */
export async function refreshRyujinxControllers(ctx: {
  emuDir: string
  run: Runner
  log: Logger
  /** Aborted when the launch stopped waiting (or PlayOut quits): nothing is written then. */
  signal?: AbortSignal
}): Promise<void> {
  const { emuDir: E, run, log, signal } = ctx
  const state = await readState(statePath(E))
  if (!state || signal?.aborted) return
  const file = await configPath(E)
  const cfg = await readConfig(file)
  if (!cfg) return
  if (signal?.aborted || (await isRyujinxRunning(run))) return
  const nextState = await mergeInto(E, cfg, run, log, state)
  if (!nextState) return
  // The launch may have gone ahead meanwhile: never rewrite Config.json under a starting Ryujinx.
  if (signal?.aborted || (await isRyujinxRunning(run)) || signal?.aborted) {
    log.info('Ryujinx controller refresh abandoned; it applies at the next launch')
    return
  }
  await writeConfig(file, cfg)
  await writeState(statePath(E), nextState)
}
